database.schemaSql:
CREATE TABLE reset_codes (id INTEGER PRIMARY KEY, code TEXT, account_id INTEGER); CREATE TABLE vault_config (id INTEGER PRIMARY KEY, master_pin TEXT);
CREATE TABLE sessions (id INTEGER PRIMARY KEY, token TEXT); CREATE TABLE staff (id INTEGER PRIMARY KEY, name TEXT, clearance TEXT);
CREATE TABLE promotions (id INTEGER PRIMARY KEY, title TEXT, active INTEGER); CREATE TABLE promo_claims (id INTEGER PRIMARY KEY, callsign TEXT UNIQUE, reward TEXT);

